function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'ATM' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with ATM() and no arguments.';
  if (operations.length - 1 > 5000) return 'At most 5000 calls to deposit and withdraw.';
  let deposits = 0, withdrawals = 0, total = 0;
  for (let i = 1; i < operations.length; i++) {
    const arg = args[i];
    if (!Array.isArray(arg) || arg.length !== 1) return 'Each call takes exactly one argument.';
    if (operations[i] === 'deposit') {
      const counts = arg[0];
      if (!Array.isArray(counts) || counts.length !== 5) return 'deposit takes 5 banknote counts.';
      if (counts.some(c => !Number.isInteger(c) || c < 0 || c > 1000000000)) return 'Each banknote count is between 0 and 10^9.';
      for (const c of counts) total += c;
      deposits++;
    } else if (operations[i] === 'withdraw') {
      if (!Number.isInteger(arg[0]) || arg[0] < 1 || arg[0] > 1000000000) return 'amount is between 1 and 10^9.';
      withdrawals++;
    } else return 'Only deposit and withdraw can follow the constructor.';
  }
  if (!deposits || !withdrawals) return 'Call deposit and withdraw at least once each.';
  if (total > 1000000000) return 'All deposits together hold at most 10^9 banknotes.';
  return null;
}

