class ATM {
  constructor() {
    this.values = [20, 50, 100, 200, 500];
    this.counts = [0, 0, 0, 0, 0];
  }

  deposit(banknotesCount) {
    for (let i = 0; i < 5; i++) {
      this.counts[i] += banknotesCount[i];
    }
  }

  withdraw(amount) {
    const taken = [0, 0, 0, 0, 0];
    let remaining = amount;
    for (let i = 4; i >= 0; i--) {
      taken[i] = Math.min(this.counts[i], Math.floor(remaining / this.values[i]));
      remaining -= taken[i] * this.values[i];
    }
    if (remaining !== 0) {
      return [-1];
    }
    for (let i = 0; i < 5; i++) {
      this.counts[i] -= taken[i];
    }
    return taken;
  }
}

