class ATM {
  constructor() {
    this.bank = new Map([[500, 0], [200, 0], [100, 0], [50, 0], [20, 0]]);
  }
  deposit(banknotesCount) {
    [20, 50, 100, 200, 500].forEach((v, i) => this.bank.set(v, this.bank.get(v) + banknotesCount[i]));
  }
  withdraw(amount) {
    const plan = new Map();
    let left = amount;
    for (const [v, have] of this.bank) {
      let lo = 0, hi = have;
      while (lo < hi) {
        const m = lo + Math.ceil((hi - lo) / 2);
        if (m * v <= left) lo = m; else hi = m - 1;
      }
      plan.set(v, lo);
      left -= lo * v;
    }
    if (left !== 0) return [-1];
    for (const [v, t] of plan) this.bank.set(v, this.bank.get(v) - t);
    return [20, 50, 100, 200, 500].map(v => plan.get(v));
  }
}

