function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const values = [20, 50, 100, 200, 500];
  const large = size === 'large';
  const calls = large ? 499 : int(2, 12);
  const depositShare = large ? int(1, 5) / 10 : 0.4;
  const kinds = Array.from({ length: calls }, () => rand() < depositShare ? 'deposit' : 'withdraw');
  if (!kinds.includes('deposit')) kinds[0] = 'deposit';
  if (!kinds.includes('withdraw')) kinds[calls - 1] = 'withdraw';
  const perNote = large ? int(1, 400000) : 3;
  const operations = ['ATM'];
  const args = [[]];
  for (const kind of kinds) {
    operations.push(kind);
    if (kind === 'deposit') {
      args.push([values.map(() => rand() < 0.3 ? 0 : int(0, perNote))]);
    } else {
      let amount;
      const pick = rand();
      if (pick < 0.6) {
        amount = 0;
        const notes = large ? int(1, 4000) : int(1, 5);
        for (let j = 0; j < 5; j++) amount += values[j] * Math.floor(rand() * notes);
        if (amount === 0) amount = values[int(0, 4)];
      } else if (pick < 0.85) {
        amount = 10 * int(1, large ? 100000000 : 100);
      } else {
        amount = int(1, large ? 1000000000 : 1000);
      }
      args.push([Math.min(amount, 1000000000)]);
    }
  }
  return [operations, args];
}
